import re

# Read raw content
with open('/workdir/data/books.json', 'r') as f:
    books_raw = f.read()

# Strategy: Use regex to find all complete book objects
# Each book object starts with { and ends with }, with balanced braces

def extract_balanced_braces(text, start_idx):
    """Find the matching closing brace for the opening brace at start_idx"""
    depth = 0
    i = start_idx
    while i < len(text):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1  # No matching brace found

def parse_book_object(obj_str):
    """Parse a book object string into a dict"""
    obj = obj_str.strip()
    # Remove outer braces
    if obj.startswith('{') and obj.endswith('}'):
        obj = obj[1:-1]
    else:
        return None

    result = {}

    # Extract title - look for "title": "value" or 'title': 'value'
    # Handle both quote types
    title_match = re.search(r'"title"\s*:\s*"?([^"\'"]+)"?', obj)
    if not title_match:
        title_match = re.search(r"'title'\s*:\s*'([^']*)'", obj)
    if title_match:
        result['title'] = title_match.group(1)

    # author
    author_match = re.search(r'"author"\s*:\s*"?([^"\'"]+)"?', obj)
    if not author_match:
        author_match = re.search(r"'author'\s*:\s*'([^']*)'", obj)
    if author_match:
        result['author'] = author_match.group(1)

    # year - can be number or string
    year_match = re.search(r'"year"\s*:\s*(\d+)', obj)
    if not year_match:
        year_match = re.search(r'"year"\s*:\s*"(\d+)"', obj)
        if year_match:
            year_match = re.search(r'"year"\s*:\s*"(\d+)"', year_match.group(0))
    if not year_match:
        year_match = re.search(r"'year'\s*:\s*'(\d+)'", obj)
    if year_match:
        result['year'] = int(year_match.group(1))
    else:
        # Try to get year from string that might have quotes
        year_match = re.search(r'year[^:]*:\s*"?(\d+)"?', obj)
        if year_match:
            result['year'] = int(year_match.group(1))

    # genre
    genre_match = re.search(r'"genre"\s*:\s*"?([^"\'",]+)"?', obj)
    if not genre_match:
        genre_match = re.search(r"'genre'\s*:\s*'([^']*)'", obj)
    if genre_match:
        result['genre'] = genre_match.group(1).strip()

    # pages
    pages_match = re.search(r'"pages"\s*:\s*(\d+)', obj)
    if not pages_match:
        pages_match = re.search(r'"pages"\s*:\s*"(\d+)"', obj)
    if not pages_match:
        pages_match = re.search(r"'pages'\s*:\s*'(\d+)'", obj)
    if pages_match:
        result['pages'] = int(pages_match.group(1))

    return result

# Extract all books
books = []
i = 0
while i < len(books_raw):
    if books_raw[i] == '{':
        end = extract_balanced_braces(books_raw, i)
        if end != -1:
            obj_str = books_raw[i:end+1]
            book = parse_book_object(obj_str)
            if book and 'title' in book:
                books.append(book)
            i = end + 1
        else:
            break
    else:
        i += 1

print(f"Extracted {len(books)} books")
for i, b in enumerate(books[:5]):
    print(f"{i}: {b}")

# Now do the same for prices
with open('/workdir/data/book_prices.json', 'r') as f:
    prices_raw = f.read()

prices = []
i = 0
while i < len(prices_raw):
    if prices_raw[i] == '{':
        end = extract_balanced_braces(prices_raw, i)
        if end != -1:
            obj_str = prices_raw[i:end+1]

            # Parse title
            title_match = re.search(r'"title"\s*:\s*"?([^"\'"]+)"?', obj_str)
            if not title_match:
                title_match = re.search(r"'title'\s*:\s*'([^']*)'", obj_str)
            if title_match:
                title = title_match.group(1)
            else:
                continue

            # Parse price
            price_match = re.search(r'"price"\s*:\s*([0-9.]+)', obj_str)
            if not price_match:
                price_match = re.search(r'"price"\s*:\s*"([0-9.]+)"', obj_str)
            if price_match:
                price = float(price_match.group(1))
            else:
                continue

            prices.append({'title': title, 'price': price})
            i = end + 1
        else:
            break
    else:
        i += 1

print(f"Extracted {len(prices)} prices")
for i, p in enumerate(prices[:5]):
    print(f"{i}: {p}")

# Now join them
print("\n--- Joining books and prices ---")
price_map = {p['title']: p['price'] for p in prices}
print(f"Price map has {len(price_map)} entries")

# Find books without prices
books_with_prices = [b for b in books if b['title'] in price_map]
print(f"Books with prices: {len(books_with_prices)}")
